const items = $input.all();
const response = items[0].json;

let criticAnalysis = '';
if (response.message && response.message.content) {
  criticAnalysis = response.message.content;
} else if (response.response) {
  criticAnalysis = response.response;
} else {
  criticAnalysis = 'ERROR: Could not extract critic analysis from response';
}

return [{
  json: {
    criticAnalysis,
    criticModel: 'deepseek-r1:14b',
