const items = $input.all();
const response = items[0].json;

let promoterOutput = '';
if (response.message && response.message.content) {
  promoterOutput = response.message.content;
} else if (response.response) {
  promoterOutput = response.response;
} else {
  promoterOutput = 'ERROR: Could not extract promoter decision';
}

const upperOutput = promoterOutput.toUpperCase().trim();
let verdict = 'KILL';
if (upperOutput.startsWith('PROMOTE') || upperOutput.includes('DECISION: PROMOTE') || upperOutput.includes('VERDICT: PROMOTE')) {
  verdict = 'PROMOTE';
} else if (upperOutput.startsWith('REVISE') || upperOutput.includes('DECISION: REVISE') || upperOutput.includes('VERDICT: REVISE')) {
  verdict = 'REVISE';
}

return [{
  json: {
    verdict,
    promoterOutput,
    promoterModel: 'qwen3',
    prosecutorFindings: $('Parse Prosecutor Output').json.prosecutorFindings,
    criticAnalysis: $('Parse Critic Output').json.criticAnalysis,
    strategyDSL: $('Parse Proposer Output').json.strategyDSL,
    rawProposerOutput: $('Parse Proposer Output').json.rawProposerOutput,
    timestamp: new Date().toISOString()
  }
}];
